INSERT INTO `posts` (`id`, `title`, `content`, `summary`, `slug`, `created_at`, `category_id`, `is_featured`, `is_published`, `published_at`, `updated_at`, `author`, `thumbnail`, `type`) VALUES
(5, 'Khai mạc tuần lễ Chuyển đổi số quốc gia 2024 tại Hà Nội', 'Chương trình diễn ra với nhiều hoạt động hội thảo chuyên sâu về trí tuệ nhân tạo và dữ liệu số.\n\nPhát biểu tại buổi lễ, đại diện Ủy ban nhấn mạnh tầm quan trọng của việc kết nối dữ liệu giữa các địa phương.', 'Sự kiện thu hút hơn 500 đại biểu và các chuyên gia công nghệ hàng đầu tham dự.', 'khai-mac-tuan-le-chuyen-oi-so-quoc-gia-2024-tai-ha-noi', '2026-04-04 01:02:39.623774', NULL, 1, 1, '2026-04-03 18:02:39', '2026-04-11 00:06:26.013314', 'Nguyễn Văn A', 'data:image/png;base64,', NULL);
INSERT INTO `posts` (`id`, `title`, `content`, `summary`, `slug`, `created_at`, `category_id`, `is_featured`, `is_published`, `published_at`, `updated_at`, `author`, `thumbnail`, `type`) VALUES
(6, 'Ra mắt ứng dụng công dân số tích hợp nhiều tiện ích mới', 'Ứng dụng mới giúp giảm thiểu thời gian chờ đợi và minh bạch hóa quá trình xử lý hồ sơ.\n\nHệ thống hỗ trợ xác thực bằng khuôn mặt và vân tay bảo mật cao.', 'Người dân có thể thực hiện 100% thủ tục hành chính qua ứng dụng di động.', 'ra-mat-ung-dung-cong-dan-so-tich-hop-nhieu-tien-ich-moi', '2026-04-04 01:02:39.637970', NULL, 0, 1, '2026-04-03 18:02:39', '2026-04-11 00:06:26.013314', 'Trần Thị B', 'data:image/png;base64,', NULL);
INSERT INTO `posts` (`id`, `title`, `content`, `summary`, `slug`, `created_at`, `category_id`, `is_featured`, `is_published`, `published_at`, `updated_at`, `author`, `thumbnail`, `type`) VALUES
(7, 'Thông báo về việc tạm ngưng hệ thống để bảo trì định kỳ', 'Để nâng cấp hạ tầng mạng và đảm bảo an toàn thông tin, chúng tôi xin thông báo lịch bảo trì như sau:\n\n1. Thời gian: 22:00 ngày 05/04 đến 04:00 ngày 06/04.\n2. Các dịch vụ ảnh hưởng: Cổng dịch vụ công, Hệ thống một cửa điện tử.\n\nTrân trọng cảm ơn sự hợp tác của quý dân cư.', 'Hệ thống dịch vụ công sẽ tạm ngưng từ 22h tối thứ 7 đến 4h sáng chủ nhật.', 'thong-bao-ve-viec-tam-ngung-he-thong-e-bao-tri-inh-ky', '2026-04-04 01:02:39.642488', NULL, 0, 1, '2026-04-03 18:02:39', '2026-04-11 00:06:25.971731', 'Trung tâm CNTT', 'data:image/png;base64,', NULL);
