(1, 'Đăng ký khai sinh', 'Hồ sơ gồm CMND, giấy chứng sinh...', '2026-03-28 23:08:34.706948', '', NULL, NULL, NULL, NULL, '[[],[],[],[]]', 'data:image/png;base64,', NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899');
INSERT INTO `procedures` (`id`, `title`, `description`, `created_at`, `content`, `required_documents`, `processing_time`, `fee`, `form_url`, `steps`, `thumbnail`, `slug`, `summary`, `type`, `author`, `category_id`, `is_featured`, `is_published`, `published_at`, `updated_at`) VALUES
(2, 'Đăng ký kết hôn', 'Hồ sơ gồm CMND, hộ khẩu...', '2026-03-28 23:08:34.706948', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899'),
(3, 'Cấp giấy xác nhận', 'Mô tả...', '2026-04-03 22:00:41.963171', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899'),
(4, 'Đăng ký tạm trú', 'Mô tả...', '2026-04-03 22:00:41.963171', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899'),
(5, 'Đăng ký tạm trú cho công dân', 'Thủ tục đăng ký tạm trú khi công dân chuyển đến sinh sống tại địa bàn xã/phường.', '2026-04-04 01:08:06.289173', 'Lưu ý: Công dân cần có tài khoản Định danh điện tử (VNeID) mức 2 để thực hiện nhanh nhất.', '1. Tờ khai CT01;\n2. Hợp đồng thuê nhà/Sổ đỏ;\n3. CCCD gắn chip.', '03 ngày làm việc', 'Miễn phí', 'https://dichvucong.gov.vn/', '[{\"title\":\"Bước 1: Chuẩn bị hồ sơ\",\"detail\":\"Công dân chuẩn bị đầy đủ các giấy tờ theo danh mục hồ sơ yêu cầu.\"},{\"title\":\"Bước 2: Nộp hồ sơ\",\"detail\":\"Nộp trực tiếp tại Công an xã hoặc nộp trực tuyến qua Cổng dịch vụ công.\"},{\"title\":\"Bước 3: Tiếp nhận & Xử lý\",\"detail\":\"Cơ quan chức năng kiểm tra tính xác thực và cập nhật vào CSDL cư trú.\"},{\"title\":\"Bước 4: Trả kết quả\",\"detail\":\"Công dân nhận thông báo kết quả qua tin nhắn hoặc nhận trực tiếp.\"}]', NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899'),
(6, 'Cấp bản sao trích lục hộ tịch (Khai sinh, kết hôn...)', 'Cấp bản sao các giấy tờ hộ tịch từ sổ gốc của cơ quan nhà nước.', '2026-04-04 01:08:06.297752', 'Bước 1: Người yêu cầu điền tờ khai theo mẫu.\nBước 2: Xuất trình giấy tờ tùy thân (CCCD).\nBước 3: Công chức tư pháp - hộ tịch kiểm tra và trích lục từ sổ gốc.', '1. Tờ khai yêu cầu cấp bản sao trích lục hộ tịch;\n2. Bản chính hoặc bản sao có chứng thực CCCD của người yêu cầu.', 'Trong ngày làm việc', '8.000 VNĐ / bản sao', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899'),
(7, 'Cấp bản sao trích lục hộ tịch', 'Cấp bản sao các giấy tờ hộ tịch từ sổ gốc.', '2026-04-04 01:12:47.312401', 'Có thể yêu cầu cấp nhiều bản sao cùng một lúc.', '1. Tờ khai yêu cầu;\n2. Giấy tờ tùy thân.', 'Ngay trong ngày', '8.000 VNĐ / bản', '', '[{\"title\":\"Bước 1: Điền thông tin\",\"detail\":\"Điền thông tin vào tờ khai tại bộ phận Một cửa.\"},{\"title\":\"Bước 2: Kiểm tra sổ gốc\",\"detail\":\"Công chức tư pháp đối chiếu thông tin với sổ đăng ký hộ tịch gốc.\"},{\"title\":\"Bước 3: Đóng lệ phí\",\"detail\":\"Nộp lệ phí tại quầy thu ngân.\"},{\"title\":\"Bước 4: Nhận bản sao\",\"detail\":\"Ký tên vào sổ và nhận các bản sao trích lục.\"}]', NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, NULL, '2026-04-11 00:59:58.155899');

